window.K3_QRAW = window.K3_QRAW || [];
window.K3_QRAW.push.apply(window.K3_QRAW, [{"id": "edu-psych|xl-08|b87|7", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 7, "q": "根据科尔伯格道德发展理论，下列取向中属于习俗水平的是（）", "opts": ["社会契约取向", "惩罚和服从取向", "工具性的相对主义取向", "好孩子取向"], "a": 3, "exp": "科尔伯格运用道德两难法，将儿童的道德认知发展分成了三水平六阶段，前习俗水平包括惩罚与服从道德定向阶段和相对功利道德定向阶段，习俗水平包括寻求括社会契约定向阶段和普遍原则的道德定向阶段，而题目中的选项，只有好孩子取向是属于习俗水平的，因此D选项是正确的。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b87|8", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 8, "q": "学生李明在上学的路上，因帮助突然生病的路人而迟到。老师征询大家的意见，是否按班规对李明进行处罚。张阳认为，李明帮助别人是对的，不应该处罚他。张阳的道德发展水平最可能处于（）", "opts": ["前习俗水平", "习俗水平", "后习俗水平", "中习俗水平"], "a": 2, "exp": "社会契约定向阶段属于后习俗水平，认为法律可以帮助人维持公正，但法律并不是绝对的，可以应大多数人的要求而改变。普追原则的道德定向阶段，以公正、平等、尊严这些最一般的原则为标准进行思考，进行某些活动时，认为只要动机是好的，行为就是正确的。题干中，张阳认为李明帮助别人是对的，不应该处罚他，说明张阳能够根据行为的动机来对别人的行为作出判断，因此他的道德发展水平处于“普遍原则的道德定向阶段”，即“后习俗水平”，符合题意。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|9", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 9, "q": "学校教育产生的基本社会条件是", "opts": ["语言的形成", "文字的出现", "生产劳动", "人的意识的形成"], "a": 1, "exp": "学校教育产生，传说是在原始社会后期，一般在夏商西周时期才逐渐成型，基本的社会条件是产生了文字，如甲骨文，改变了原始人“结绳记事”的方式。本题可以倒推思考，原始人是有语言功能的、会从事生产劳动、也有人的意识，只是因为没有成熟的文字，不好对下一代进行较为系统的学校教育。因此本题最合适的选项是B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|10", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 10, "q": "根据《中国教育现代化2035），我国在大力推进教育理念、体系、制度、内容、方法现代化的同时，还要求大力推进", "opts": ["教育评价现代化", "教育系统现代化", "教育结构现代化", "教育治理现代化"], "a": 3, "exp": "本题为对教育热点的考查。根据《中国教育现代化2035》,我国在大力推进教育理念、体系、制度、内容、方法现代化的同时，还要求大力推进教育治理现代化。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|11", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 11, "q": "许多社会活动都能影响人的身心发展。相比之下，学校教育是有目的、有计划、有组织地对受教育者的身心施加影响的活动。其中，最集中而系统地体现学校教育之“有计划”特征的是", "opts": ["国家教育发展规划", "学校教育制度", "课程", "教案"], "a": 2, "exp": "注意题干询问的是“最集中而系统地体现”，虽然其他选项也与学校教育有关，但是要找出最能体现“有计划”特征的选项，需要考虑哪个选项在规划和组织学生的身心发展方面起到最为集中和系统的作用。A选项，国家教育发展规划是对整个国家教育体系的规划，确定的是整个国家教育体系的发展方向，虽然重要，但不直接对受教育者的身心施加有计划的影响，过于宏观。B选项，学校教育制度是指学校的管理体制和规章制度，如明确小学读几年、中学读几年等，虽然对学校教育的组织和运行有影响，但不直接对受教育者的身心发展施加影响。D选项，教案是教师为教学活动编写的详细教学计划，虽然是教学的重要组成部分，但相比于课程，教案更侧重于具体的教学过程和方法，过于微观。课程是为了实现各级各类学校的培养目标而规定的所有学科（即教学科目）及其目的、内容、范围、活动、进程等的综合。它主要体现在课程计划、课程标准和教材（教科书)中。综上所述，A、B、D选项均不符合题意，本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|12", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 12, "q": "将儿童当作“小大人”对待，这违背了个体身心发展的", "opts": ["阶段性和顺序性", "整体性和系统性", "稳定性和可变性", "不平衡性和差异性"], "a": 0, "exp": "当将儿童当作“小大人”对待时，违背了个体身心发展的阶段性和顺序性（A选项）。儿童发展是分阶段的，有儿童阶段和成年阶段，不能不重视阶段特征。如果把儿童当作小大人看待，无法做到循序渐进，也违背发展的顺序性。B选项，整体性和系统性：整体性和系统性指个体身心发展的整体性和系统性特征，即身心发展是一个整体且相互关联的系统。虽然这也是身心发展的重要特征，但不直接涉及将儿童当作“小大人”对待的问题。C选项，稳定性和可变性：稳定性和可变性指个体身心发展中稳定的特征和可变的特征。附录附录。将儿童当作“小大人”对待可能会忽视他们身心发展中的可变性，但这并不是主要方面，口;主尝时间、达到的成熟水平不同。如一个个体，神经系统先于生殖系统成熟。二是同一系统机能在发展的不同时期有不同的发展速度。如人的身高，在背春期的发展速度要快于在成年期的发展速度。不平衡性要求抓住人发展的关键期，和题目无关。差异性指的是不同的儿童之间的差异，和题目无关。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|13", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 13, "q": "有一种课程主要围绕人类基本活动来确定不同年级学生学习的主题，如1一2年级学习周围的环境，包括家庭、学校和所在社区；3一4年级学习较广的环境，由县、省到国家...9一10年级学习社会经济，这种课程称之为", "opts": ["综合课程", "核心课程", "学科活动", "分科课程"], "a": 1, "exp": "核心课程也叫作问题课程，它以问题为核心，将几门知识综合起来。其在形式上，采取由近及远、由内向外、逐步拓展的顺序呈现课程内容。题目中的课程明确以“人类基本活动”这个问题为核心，1一2年级、3一4年级··9一10年级逐步拓展，由近及远，符合核心课程的定义，故选B选项。A选项，综合课程包含相关课程、融合课程、广域课程、核心课程，过于宽泛，不选。C选项，学科活动是以学科为核心展开的活动，如围绕语文学科、数学学科开展的活动，不选。D选项，分科课程强调课程分科，如将课程分为语文课、数学课、英语课等，不选。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|14", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 14, "q": "将两门或多门学科内容整合在一门课程中，打破学科界限，体现这种课程编制方法的课程类型包括", "opts": ["融合课程、广域课程、核心课程", "核心课程、相关课程、融合课程", "相关课程、融合课程、广域课程", "广域课程、核心课程、相关课程"], "a": 0, "exp": "综合课程包含相关课程、融合课程、广域课程、核心课程。相关课程没有打破学科界限，可直接排除，故本题选A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|15", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 15, "q": "我国义务教育阶段开设的《道德与法治》属于", "opts": ["分科课程", "综合课程", "核心课程", "活动课程"], "a": 1, "exp": "我国义务教育阶段开设的“道德与法治”涵盖了思想品德内容、法律基础内容，同时包含一些心理学、社会学的知识，故属于综合课程选B选项。A选项，分科课程强调课程的独立性，如语文课就是语文课，数学课就是数学课。“道德与法治\"涵盖了多门学科的知识793637888C选项，核心课程强调两个点，一是围绕问题展开，二是由近及远、由内向外、逐步拓展。“道德与法治”课未体现。D选项，活动课程与学科课程相对，以杜威提出的活动课为典型代表，如烹饪课、纺织课等。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|16", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 16, "q": "某小学数学教研组开发了“生活中的分段计费”校本课程。教师先在课堂上指导学生了解出租车的计费规则，再让学生分组收集并分析近一年家庭用水、用电、用气的数据，形成《生活中的分段计费》研究报告。这样的课程属于", "opts": ["文献课程", "项目式课程", "综合课程", "大单元课程"], "a": 1, "exp": "项目式课程设计侧重于让学生通过实际项目的参与和完成来学习知识和技能，并以此培养他们的解决问题能力和团队合作精神。在题目所述的例子中，学生通过分组收集和分析家庭用水、用电、用气的数据，形成研究报告，实际应用数学知识解决实际问题，符合项目式课程的设计理念。A选项，文献课程：文献课程通常指以文献为主要内容的课程，如孔子以《诗》《书>《礼》等典籍教学。C选项，综合课程：综合课程包含相关课程、融合课程、广域课程、核心课程。D选项，大单元课程：大单元课程通常指将多个相关主题或单元整合在一起，形成一个较大的学习单元，帮助学生更全面地理解和掌握知识的课程。A、C、D选项均不符合题意，本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|17", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 17, "q": "2001年启动的基础教育课程改革，“倡导学生主动参与、乐于探究、勤于动手”，其目的在于交流与合作的能力", "opts": ["", "使学生获得终身发展所必需的知识", "提高学生的基础学力", "培养学生的创造性和开放性思维"], "a": 0, "exp": "2001年启动的基础教育课程改革，倡导学生主动参与、乐于探究、勤于动手，其目的在于培养学生搜集和处理信息的能力、获取新知识的能力、分析和解决问题的能力以及交流与合作的能力，A选项正确。这一教育改革旨在培养学生全面发展，提高他们的综合能力，包括信息处理能力、问题解决能力、交流与合作能力等，以适应未来社·附录一全国硕士研究生招生考试教育专业学位硕士教育综合考试样卷参考答案会的需求和挑战。B选项，使学生获得终身发展所必需的知识：这个选项指教育的目的是让学生获得他们终身发展所必需的知识，以便他们在未来的生活和工作中能够持续学习和成长。C选项，提高学生的基础学力：这个选项指教育的目的是提高学生的基础学力，包括基本的学科知识和技能，以确保他们在学业上有扎实的基础。D选项，培养学生的创造性和开放性思维：这个选项指的是教育的目的是培养学生的创造性和开放性思维，激发他们的创造力和创新能力，以适应未来社会的变化和挑战。导学生主动参与、乐于探究、勤于动手”主要目的是培养学生搜集和处理信息的能力、获取新知识的能力、分析和解决问题的能力以及交流与合作的能力，以适应当时社会的需求和教育理念的转变。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|18", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 18, "q": "“理论联系实际”是我国长期遵循的一条基本教学原则。这个原则的实质，是要求教师解决好教学过程中", "opts": ["掌握知识与提高能力的关系", "教师主导作用与学生主体作用的关系", "间接经验与直接经验的关系", "智力因素与非智力因素的关系"], "a": 2, "exp": "理论所代表的知识，一般是间接经验，是由前人总结出来的。实践则强调学习者的亲自参与，以获得直接经验。C选项最合适。A选项，掌握知识与提高能力的关系不合适，因为不能简单地将“理论”等同于“知识”，“实践”等同于“能力”。B选项，教师主导作用与学生主体作用的关系不合适。理论不是教师的专属，实践也不完全是学生才能做。D选项，智力因素与非智力因素的关系体现不出理论和实践的关系。智力因素是学生的思考能力、理解能力、想象能力等，非智力因素如学生的情感、动机、与教师的关系等，与题目无关。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|19", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 19, "q": "为了满足全区中小学生家长获得优质学习资源的需求，某区县围绕各年级学生心理发展过程中可能出现的突出问题设计开发了60个小视频，每个视频20分钟，分别制作成二维码，向全区家长推送，便于家长利用空闲时间自主学习，并通过各种类型的家长沙龙活动面对面进行经验交流分享。这套教学设计指向的学习方式是", "opts": ["探究学习、问题学习、泛在学习", "泛在学习、混合学习、探究学习", "问题学习、泛在学习、混合学习", "混合学习、问题学习、探究学习"], "a": 2, "exp": "此类型的题目，必须紧密结合题干来选。“某区县围绕各年级学生心理发展过程中可能出现的突出问题”体现的是问题学习。“设计开发了60个小视频，每个视频20分钟，分别制作成二维码，向全区家长推送，便于家长利用空闲时间自主学习”体现的是泛在学习，即任何时间、任何地点，可以随时随地学习。“并通过各种类型的家长沙龙活动面对面进行经验交流分享”代表既有线上观看视频的学习，又有线下的沟通和讨论，属于线上+线下的混合学习。故本题选C选项。其他选项中的“探究学习”，一般指学习者主动发现问题、解决问题、建构知识的过程，题目中没有体现。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|20", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 20, "q": "班级授课制之所以仍是当今世界最主要的教学组织形式，根本在于它", "opts": ["公平", "师生互动频繁", "高效", "以教师为中心"], "a": 2, "exp": "通过班级授课制，教师可以一次性向整个班级传授知识，实现批量教学，提高教学效率。这种集体学习的方式可以让教师在有限的时间内覆盖更多的学生，促进知识的传播和学习的进展。因此，高效性是班级授课制成为当今世界最主要的教学组织形式的重要原因之一。在班级授课制下，教师很难真正关注到每一个学生，很难真正做到因材施教，甚至可能无意识地忽略一些学生，因此排除A选项公平。在班级授课制下，师生互动也无法做到很频繁，排除B选项。至于D选项，班级授课制的确是以教师为中心的，但是我们现在的教育理念不是强调完全以教师为中心，而是教师主导和学生主体相结合，所以D选项是班级授课制的缺陷而不是其优势。一个事物能被推广、占主流，一定是选择其优势的部分，而不是说因为其有附录。某种劣势所以占主导，这是不符合逻辑的，故排除D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|21", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 21, "q": "根据班杜拉的社会学习理论，促进学生良好道德行为形成和发展，最宜采用的方法是", "opts": ["榜样示范", "情境陶冶", "实践锻炼", "说服教育"], "a": 0, "exp": "班杜拉是社会学习理论的代表人物，注重培养学生的社会行为，强调学生通过观察榜样行为进行学习，因此，A选项榜样示范是最宜采用的方法。其他选项不符合班杜拉的社会学习理论。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|22", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 22, "q": "任何教学组织形式的提出都有其问题指向，都试图解决教学中存在的某个具体问题。翻转课堂试图解决的主要问题是", "opts": ["合作探究", "以学定教", "微课运用", "逆向设计"], "a": 1, "exp": "传统的教学组织形式是教师在课上讲，学生课后做作业。翻转课堂的形式是，学生在课后看教师录制的课程视频，课上教师根据学生的学习答疑解惑。其想要推进的是“以学定教”，即根据学生学习的结果，来推动教师教的内容和进程。A选项，合作探究强调人与人之间的合作，与翻转课堂无关。C选项，微课运用只是一种形式，指的是教师录制课程小视频，可以看成是翻转课堂的一种方式，而非其想要达成的目的。D选项，逆向设计指的是根据最终要达成的目的，来设计学习或者教学的过程，强调“以终为始”。本题题干中的“问题”不是贬义的，“试图解决的主要问题”可以理解为“想要达到的目的或者效果”，B选项是最合适的。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|23", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 23, "q": "教育情境的不可复制性是教育活动的突出特点，反映了教师劳动具有", "opts": ["整合性", "示范性", "长期性", "创造性"], "a": 3, "exp": "创造性。故本题选D选项。教育情境中的每个学生都是独一无二的个体，每堂课、每次互动都会因学生的不同反应而产生变化。这要求教师具备创造性，能够灵活应对不同的情境和学生需求，创造出适合特定情况的教学方法和策略。A选项，整合性：教师劳动的整合性指的是教师需要整合各种资源、知识和技能，设计和实施教学活动，使之成为有机的整体888B选项，示范性：教师劳动的示范性指的是教师在教学中扮演的示范和引领角色，通过自身言行影响学生。C选项，长期性：教师劳动的长期性指的是教师需要持续投人时间和精力，长期指导和关注学生的成长和发展。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|24", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 24, "q": "孔子关于启发教学的具体主张是", "opts": ["臂如撞钟，扣则鸣，不扣则不鸣", "学然后知不足，教然后知困", "道而弗牵，强而弗抑，开而弗达", "不愤不启，不排不发"], "a": 3, "exp": "本题为对识记性知识的考查。D选项“不愤不启，不排不发”为孔子所提。朱熹释义：“愤者，心求通而未得之意，排者，口欲言而未能之貌”。即不到学生努力想弄明白但仍然想不透的程度时，先不要去开导他；不到学生心里明白却又不能完善表达出来的程度时，不要去启发他。其他选项释意分别为：A选项，臂如撞钟，扣则鸣，不扣则不鸣：这句话出自《墨子》，但并非墨子的思想，而是儒家学者在与墨子对话时，同墨子言：回答学生的问题就应像撞钟一样，学生问了再回答，不问就不管。对此墨子进行了辩驳，提出“虽不扣必鸣”，强调即便学生不问，也要主动对学生进行教育。B选项，学然后知不足，教然后知困：这句话出自《学记》，意思是学习才知道自己有哪里不会，教师在教别人的过程中，才知道自己有哪里没有搞明白。所以教师以教为学，代表教学相长的原则。C选项，道而弗牵，强而弗抑，开而弗达：这句话出自《学记》，意思是要引导学生自己学习而不是强制学生学习，要鼓励学生学习而不是压抑学生的学习热情，要启发学生而不是附录一全国硕士研究生招生考试教育专业学位硕士教育综合考试样卷参考答案直接把答案告诉学生。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|25", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 25, "q": "根据孟子的性善论，仁义礼智“我固有之”，其中恭敬之心是", "opts": ["仁之端", "义之端", "礼之端", "智之端"], "a": 2, "exp": "本题为对识记性知识的考查，孟子提出四心，其中“侧隐之心，仁也；羞恶之心，义也；恭敬之心，礼也；是非之心，智也。”故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|26", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 26, "q": "东汉设立鸿都门学的起因是为了", "opts": ["崇尚文学", "倡导艺术", "培养专才", "培植政派"], "a": 3, "exp": "东汉设立鸿都门学的起因是宦官集团为了培养拥护自己的知识分子。鸿都门学的确是世界上最早的文学艺术的专门学校，A、B、C选项都符合其建立后的基本史实，但是题目问的是起因，A、B、C选项可以看作是建立后的结果，从起因来看，D选项是最合适的。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|27", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 27, "q": "唐代的地方官学中除经学外，存在较长时间的还有", "opts": ["书学", "算学", "律学", "医学"], "a": 3, "exp": "本题为对识记性知识的考查。唐代的地方官学中除经学外，存在较长时间的还有医学。A选项书学、B选项算学、C选项律学均为中央官学的内容，题目询问的地方官学，故排除。地方官学有经学、医学、崇玄学。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|28", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 28, "q": "中国共产党确立的新民主主义教育方针是", "opts": ["民主的、科学的、大众的文化教育", "民族的、科学的、大众的文化教育", "民主的、民族的、科学的文化教育", "民族的、民主的、大众的文化教育"], "a": 1, "exp": "，本题为对识记性知识的考查。中国共产党确立的新民主主义教育方针是民族的、科学的、大众的。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|29", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 29, "q": "在西方教育史上，致力于阐明“把一切事物教给一切人类的全部艺术”的教育著作是", "opts": ["《理想国》", "（大教学论）", "《教育学讲授纲要》", "《民主主义与教育）"], "a": 1, "exp": "本题为对识记性知识的考查。“把一切事物教给一切人类的全部艺术”是夸美纽斯提出来的，其代表作是（大教学论》。A选项《理想国》是柏拉图的著作，C选项《教育学讲授纲要》是赫尔巴特的著作，D选项《民主主义与教育》是杜威的著作。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|30", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 30, "q": "在古代希伯来的学校中，教师被称为", "opts": ["“校父”", "“古儒”", "“书吏”", "“拉比”"], "a": 3, "exp": "本题为对识记性知识的考查。在古代希伯来的学校中，教师被称为拉比。A选项“校父”是古巴比伦泥板书舍的负责人。B选项“古儒”是古印度婆罗门教育中教师的称谓。C选项“书吏”是指书写能力比较强的人。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|31", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 31, "q": "文艺复兴与宗教改革时期，具有较为完备的组织管理和高水平师资的学校类型是", "opts": ["人文主义新式学校", "新教学校", "耶稣会学校", "经院主义学校"], "a": 2, "exp": "本题为对识记性知识的考查。文艺复兴与宗教改革时期，具有较为完备的组织管理和高水平师资的学校类型是耶稣会学校。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|32", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 32, "q": "表示中学应该是", "opts": ["面向所有学生并为社会服务的机构", "面向所有学生进行筛选的机构", "面向所有学生为职业做准备的机构", "面向所有学生为升人大学做准备的机构"], "a": 0, "exp": "本题为对识记性知识的考查。1918年，美国“中等教育改组委员会”提出了（中等教育的基本原则》的报告，明确表示中学应该是面向所有学生并为社会服务的机构。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|33", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 33, "q": "在欧美现代教育思潮中，强调在教育和教学过程中发挥教师权威的教育思潮是", "opts": ["改造主义教育", "要素主义教育", "存在主义教育", "人本主义教育"], "a": 1, "exp": "本题为对识记性知识的考查。在欧美现代教育思潮中，强调在教育和教学过程中发挥教师权威的教育思潮是要素主义教育。A选项，改造主义教育从进步教育运动中分化而来，强调以社会问题为核心，主张教师进行民主、劝说的教育，并未强调教师权威。C选项，存在主义教育强调师生之间应建立信任的关系，而非教师权威。D选项，人本主义教育强调以学生为中心，反对教师权威。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|34", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 34, "q": "维果茨基把文化工具分为物质工具和心理工具两类。下列选项中，属于维果茨基所讲的心理工具的是", "opts": ["算盘", "尺子", "搜索引擎", "数字系统"], "a": 3, "exp": "维果茨基是苏联心理学家，他提出了社会文化理论，强调文化工具在认知发展中的作用。维果茨基将文化工具分为物质工具和心理工具两类。物质工具是外部实物，而心理工具则是内部的、用于调节思维和行为的符号系统。算盘、尺子都是物质工具，而搜索引尽管它涉及信息处理，但它本身是一个外部设备或软件。数字系统是一种用于表示、处理和传递数值信息的符号系统。它是数学和计算的基础，使我们能够进行计数、测量、计算和逻辑推理。数字系统通常由一组符号（如数字）和规则（如进位规则）组成，用于表示不同的数值。常见的数字系统如计算机使用的基本数字系统，基于2个符号（0和1)组成，是我们用来表示和处理数字的“语言”，它帮助我们理解和操作数量关系。附录。因此，属于维果茨基所讲的心理工具的是D选项数字系统。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|35", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 35, "q": "教师制作PPT课件时，会把重要的概念用不同的字体或颜色凸显出来。从信息加工学习理论角度看，这种做法能够促进学生的", "opts": ["选择性注意", "精细加工", "情境认知", "创造性思维"], "a": 0, "exp": "从信息加工学习理论的角度来看，教师制作PPT课件时，将重要的概念用不同的字体或颜色凸显出来，主要是为了吸引学生的注意力，帮助他们更好地聚焦关键信息。这种做法最直接的作用是促进学生的选择性注意。选择性注意是信息加工的第一步，指个体在大量信息中有选择地关注某些重要信息。通过字体、颜色等视觉手段突出关键概念，可以帮助学生快速识别并集中注意力于重要内容。B选项，精细加工：指对信息进行深层次的理解和联系，例如通过举例、类比等方式将新信息与已有知识结合。PPT中的视觉强调并不能直接促进精细加工。C选项，情境认知：强调学习与环境、情境的关系，认为知识是在特定情境中建构的。如让学生在学习加减乘除时，创设在商场买东西的情境。D选项，创造性思维：指突破常规思维，产生新颖的想法或解决方案。PPT中的视觉强调主要是为了引导注意力，而非直接激发创造性思维。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|36", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 36, "q": "根据自我决定理论，教师经常占用学生的自习课时间来安排自己的教学活动，会削弱学生的内在学习动机。因为这种做法不利于满足学生的", "opts": ["生理需求", "能力需求", "自主需求", "归属需求"], "a": 2, "exp": "自我决定理论将学生的需求划分为胜任需求、归属需求、自主需求。教师经常占用学生的自习课时间来安排自己的教学活动，会削弱学生的内在学习动机，无法满足其自主需求。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b88|37", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 37, "q": "学生学习完长方形面积的计算方法后，回家计算自己睡觉的床的面积，这种迁移属于", "opts": ["近迁移", "远迁移", "类比迁移", "逆向迁移"], "a": 1, "exp": "迁移是指将已学习的知识或技能应用到新的情境中。根据迁移的范围近迁移：指将知识或技能应用到与学习情境非常相似的情境中。例如，学生在课堂上学远迁移：指将知识或技能应用到与学习情境差异较大的情境中。例如，学生将数学中的逻辑推理应用到解决生活中的复杂问题。类比迁移：指通过发现两个不同情境之间的相似性，将知识或技能从一个情境迁移到另一个情境。逆向迁移：指新学习的内容对已有知识或技能产生影响，通常是修正或调整已有知识。学生学习完长方形面积的计算方法后，回家计算自己睡觉的床的面积。床的面积的计算方法与课堂上学到的长方形面积的计算方法非常相似，且情境差异较小，故选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|38", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 38, "q": "在第39个教师节到来之际，习近平总书记专门致信全国优秀教师代表座谈会与会教师，充分肯定以与会教师为代表的广大教师的重要贡献，号召全国广大教师以教育家为榜样，大力弘扬教育家精神，为强国建设、民族复兴伟业作出新的更大贡献。教育家精神具有丰富的内涵，其中对教师理想信念的要求是", "opts": ["心有大我、至诚报国", "启智润心、因材施教", "勤学笃行、求是创新", "言为士则、行为世范"], "a": 0, "exp": "本题为对教育热点的考查，教育家精神为：心有大我、至诚报国的理想信念，言为士则、行为世范的道德情操，启智润心、因材施教的育人智慧，勤学笃行、求是创新的躬耕态度，乐教爱生、甘于奉献的仁爱之心，胸怀天下、以文化人的弘道追求。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|39", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 39, "q": "20世纪60年代以来，许多国家相继实行教育先行战略，支持这种国家发展战略的理论是", "opts": ["社会再生产理论", "人力资本理论", "社会平衡器理论", "文化资本理论"], "a": 1, "exp": "人力资本理论强调在经济增长中，人力资本的作用大于物质资本的作用。教育投资是人力投资的主要部分，教育可以提升人的知识、技能及能力。A选项，社会再生产理论认为教育是维持和复制现有社会结构和阶级关系的重要工具。通过教育，社会将主流意识形态、文化价值观和社会分工传递给下一代，从而维持现有的社会秩序。社会再生产理论并不直接支持教育先行战略，因为它更多地关注教育如何维持社会现状，而不是通过教育推动经济发展或社会变革。C选项，社会平衡器理论认为，教育可以促进社会公平，减少社会不平等现象。通过提供平等的教育机会，弱势群体可以获得向上流动的机会，从而实现社会的平衡与稳定。虽然社会平衡器理论强调教育的重要性，但它更侧重于教育的社会公平功能，而不是将教育作为推动经济发展的核心战略。因此，它并不是教育先行战略的主要理论依据。D选项，文化资本理论由法国社会学家布迪厄提出，认为教育不仅是知识和技能的传递，还是文化资本的积累过程。文化资本理论更多关注教育对个体社会地位的影响，而不是教育对经济发展的直接推动作用。因此，它也不是教育先行战略的主要理论支持。综上所述，本题的正确答案为B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|40", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 40, "q": "华虚朋的文纳特卡制在共同要素的教学上采取了个别化的策略，所遵循的人身心发展的特点是", "opts": ["顺序性", "阶段性", "差异性", "不平衡性"], "a": 2, "exp": "华虚朋的文纳特卡制是一种强调个别化教学的教育模式，其核心理念是根据学生的个体差异进行教学。因此，它所遵循的人身心发展的特点是差异性，C选项正确。A选项，顺序性指人的身心发展遵循一定的顺序，例如从简单到复杂、从低级到高级。文纳特卡制虽然关注学生的个体发展，但并未特别强调发展的顺序性。B选项，阶段性强调人的身心发展分为不同的阶段，每个阶段有特定的特征和任务。文纳特卡制并未以阶段性作为教学的主要依据，而是更注重学生的个体差异。D选项，不平衡性指的是人的身心发展在不同方面或不同时期存在不均衡的现象。文纳特卡制并未特别关注发展的不平衡性，而是更注重学生的个体差异。期的方向变化的活动，其本质是促人向善的。A选项，曹冲称象：曹冲利用浮力原理称量大象的重量，展现了他的聪明才智。这个故事综合试题参考答案附录主要体现了曹冲的智慧和创造力，但并没有明确的教育目的或教育过程，因此不能算作教育。B选项，程门立雪：宋代学者杨时为了向程颐请教问题，在程颐门前站立等待，直到积雪覆盖了他的双脚，体现了对师长的尊重和求学的诚意。这个故事体现了尊师重道的精神，但更多是描述学生的行为，而非有目的、有计划的教育活动，因此不能算作教育。C选项，岳母刺字：岳飞的母亲在岳飞背上刺下“精忠报国”四个字，激励他忠诚报国。岳母的行为具有明确的教育目的，即通过刺字的方式对岳飞进行价值观和道德教育，符合教育的定义。D选项，公车上书：清末康有为、梁启超等人联名上书，提出变法主张，试图推动社会改革。公车上书是一种政治活动，虽然涉及思想传播，但其主要目的是推动社会改革，而非直接对个体的身心发展产生影响，因此不能算作教育。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|41", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 41, "q": "下列关于当前我国普通高中教育改革趋势的描述中，不正确的是", "opts": ["精英化发展", "特色化发展", "多样化发展", "加强与大学的衔接"], "a": 0, "exp": "当前我国普通高中教育改革的趋势主要包括多样化发展、特色化发展和加强与大学的衔接，精英化发展并不是改革的主要方向。因此，不正确的描述是A选项精英化发展。A选项，精英化发展：当前我国普通高中教育改革强调教育公平和普及，注重满足不同学生的需求，而不是只关注少数精英学生。因此，“精英化发展”不符合改革趋势。B选项，特色化发展：当前我国普通高中教育改革鼓励学校根据自身条件和学生需求，发展特色课程和教学模式，以满足学生的多样化需求。C选项，多样化发展：改革强调课程的多样化和教学方式的灵活性，为学生提供更多选择，促进个性化发展。D选项，加强与大学的衔接：当前我国普通高中教育改革注重与高等教育的衔接，例如通过综合素质评价、选修课程等方式，为学生进人大学做好准备。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|42", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 42, "q": "某生在高一学期初英语成绩不及格，经过一学期的努力，在期末考试中达到优良水平。为此，老师在班会上对其英语进步予以表扬。老师对该生的评价属于", "opts": ["相对性评价", "增值性评价", "诊断性评价", "终结性评价"], "a": 1, "exp": "老师对该生的评价属于增值性评价。（如排名）。题目中老师并未将该生的成绩与其他学生进行比较，而是关注其自身的进步，因此不属于相对性评价。B选项，增值性评价：增值性评价关注学生在学习过程中的进步和成长，强调个体在原有基础上的提高。题目中老师表扬该生从不及格到优良的进步，正是基于其自身的成长和努力，符合增值性评价的特点。C选项，诊断性评价：诊断性评价是在教学开始前或过程中，用于了解学生的学习基础、问题或困难，以便调整教学策略。题目中老师的评价发生在学期末，目的是表扬学生的进步，而非诊断问题，因此不属于诊断性评价。D选项，终结性评价：终结性评价是在教学结束后，对学生的学习成果进行总结性评定（如期末考试）。题目中虽然老师提到了期末考试成绩，但重点在于表扬学生的进步，而非单纯总结成绩，因此不完全属于终结性评价。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|43", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 43, "q": "育英中学初二(6)班的学生在老师的指导下，研究附近小区内流浪猫的生存状况，调查问题包括流浪猫的数量、饮水、饮食等信息。在此基础上，他们给爱猫人士提出建议，不仅要喂食，而且要注意喂水。该案例中，学生的学习方式主要属于", "opts": ["掌握学习", "观察学习", "接受式学习", "项目化学习"], "a": 3, "exp": "该案例中，学生的学习方式主要属于项目化学习。A选项，掌握学习：掌握学习强调通过反复练习和巩固，确保学生掌握特定的知识和技能。案例中学生的学习并非通过反复练习来掌握知识，而是通过实践和研究解决问题，附录二2024年全国硕士研究生招生考试教育综合试题参考答案281=1931637888因此不属于掌握学习。B选项，观察学习：观察学习是指学生通过观察他人的行为或现象来学习知识和技能。虽然学生可能观察了流浪猫的行为，但他们的学习不仅仅是观察，还包括调查、分析和提出建议，因此不完全属于观察学习。C选项，接受式学习：接受式学习是指学生被动接受教师传授的知识，缺乏主动探究和实践。案例中学生的学习是主动的、实践性的，而非被动接受知识，因此不属于接受式学习。D选项，项目化学习：项目化学习是一种以学生为中心的学习方式，学生通过完成一个真实的、复杂的项目，综合运用多学科知识和技能解决问题。案例中，学生在老师的指导下，通过调查流浪猫的生存状况，分析问题并提出建议，这正是一个典型的项目化学习过程。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|44", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 44, "q": "根据马卡连柯的平行教育原则，班主任在工作中应该", "opts": ["以学生集体为教育对象", "以学生个体为教育对象", "对每个学生一视同仁", "对每个学生平等投人"], "a": 0, "exp": "以学生集体为教育对象。平行教育原则的核心思想：马卡连柯认为，教育应该通过集体来影响个体，而不是直接针对个体进行教育。B选项，以学生个体为教育对象是错误的。因为平行教育原则反对直接针对个体进行教育，而是认为教育应通过集体间接影响个体。C选项，对每个学生一视同仁：虽然公平对待学生是教育的基本原则，但这并不是平行教育原则的核心内容。D选项，对每个学生平等投人：平等投人资源是教育公平的体现，与平行教育原则无关。综上所述，本题选A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|45", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 45, "q": "在因突发事件导致的学校停课期间，数字技术的有效运用使儿童能够继续接受学校教育。从儿童受教育权的角度看，此种现象表明", "opts": ["受教育权仅限于儿童和青年，且仅适用于学校和教室附录。", "受教育权严格受制于特定时空，超出这一时空就不再适用", "获取信息是公民的基本权利，但与受教育权没有密切关联", "数字化时代的受教育权以信息技术为支撑，可以超越时空限制"], "a": 3, "exp": "数字化时代的受教育权以信息技术为支撑，可以超越时空限制。A选项，“受教育权仅限于儿童和青年，且仅适用于学校和教室”这一说法本身就是错误的。受教育权不仅限于儿童和青年，也不仅限于学校和教室。数字技术的运用表明，受教育权可以通过多种形式实现，超越了传统的学校和教室。B选项，“受教育权严格受制于特定时空，超出这一时空就不再适用”表述错误。数字技术的使用证明，受教育权可以超越特定的时空限制，儿童可以在家中或其他场所继续接受教育。C选项，“获取信息是公民的基本权利，但与受教育权没有密切关联”说法错误。获取信息是受教育权的重要组成部分，尤其是在数字化时代，信息技术的运用直接支持了受教育权的实现。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|46", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 46, "q": "一位有30年教龄的历史老师上了一节公开课。课后，教研员对这位历史老师说：“这节课上得太好了！请问您花了多少时间来备这节课？”历史老师答：“对这节课，我准备了一辈子，但直接的准备大概只用了15分钟。”根据这段材料所作出的推断中，不正确的是", "opts": ["备课不能仅仅局限于研读教材", "备好课是上好课的先决条件", "备课要求老师保持终身学习的习惯", "教龄越长越不需要备课"], "a": 3, "exp": "注意题目问的是说法不正确的选项。历史老师的回答表明，备课不仅仅是短时间的教材研读，而是长期积累的结果，包括教学经验、知识储备等。历史老师的成功教学表明，充分的备课是上好课的基础。历史老师的回答“准备了一辈子”表明，备课需要教师不断学习和积累，保持终身学习的习惯。附录A、B、C选项的说法都是没有问题的，但是本题问的是说法错误的选项，故不选。D选项，教龄越长越不需要备课说法错误。虽然教龄长的教师可能直接准备时间较短，但他们仍然需要备课，只是他们的经验使得备课更高效。因此，这个选项的推断是不正确的。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|47", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 47, "q": "根据《义务教育课程方案（2022年版），义务教育课程包括国家课程、地方课程和校本课程。下列表述中正确的是", "opts": ["国家课程为学生发展奠定共同基础，其中部分课程可以选修", "地方课程由省级教育行政部门规划设置并在所有年级开设", "校本课程以综合课程形态服务学生个性化学习需求", "校本课程原则上由学生自主选择"], "a": 3, "exp": "本题考查的是文件原话。A选项，国家课程是必修课程，所有学生都必须学习，不存在选修部分。B选项，地方课程由省级教育行政部门规划设置，但并非所有年级都必须开设，具体安排因地区而异。C选项，文件中的原话是“校本课程以多种课程形态服务学生个性化学习需求”。C选项的综合课程表述错误，综合课程指的是相关课程、融合课程、广域课程、核心课程。而多种课程形态不仅仅可以有综合课程，还可以有分科课程、活动课程等，综合课程在教育学上是专有名词，不可以直接等同于多种课程形态。D选项为文件原话，表述正确，故本题选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|48", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 48, "q": "杨院土带领团队创建了中国首个理工结合、覆盖全面的水声专业，88岁时还出海做实验。他在之年接受采访时说：“我只是一颗普普通通的种子，不过是上学期间遇到过一些好老师、好同学，就像找到了肥沃的土壤，所以就长出苗了。”在影响人身心发展的因素方面，这段话强调", "opts": ["遗传素质可以决定个体的发展", "人无法选择和塑造自己的环境", "环境对人的发展具有重要作用", "人的发展完全是一个外过程"], "a": 2, "exp": "A选项，遗传素质可以决定个体的发展：表述错误，遗传素质在人的身心发展中不起决定作用。影响人的身心发展的因素是多样的。B选项，人无法选择和塑造自己的环境：表述错误。杨院士的经历表明，他通过努力和选择（如上学、与好老师和好同学互动）塑造了自己的发展环境。C选项，环境对人的发展具有重要作用：表述正确。杨院士将自己比作“种子”，将好老师和好同学比作“肥沃的土壤”，强调环境对他的成长起到了关键作用。D选项，人的发展完全是一个外过程：表述错误。杨院士并未否认自身努力的作用，而是强调环境与个人努力的结合，因此“完全外”的说法过于绝对。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|49", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 49, "q": "20世纪70年代初出现的“学习型社会”理念，把学习型社会作为未来社会形态的构想和追求目标。该理念的基本内涵是", "opts": ["学校教育应该覆盖各个年龄段的人群", "学校是幼儿教育和成人教育的主流形式", "学校在终身学习的趋势中占据着主导地位", "学校及生活的全部时间和空间都可以用于教育"], "a": 3, "exp": "A选项，学校教育应该覆盖各个年龄段的人群：表述错误。学习型社会不仅限于学校教育，而是强调全社会范围内的终身学习。B选项，学校是幼儿教育和成人教育的主流形式：表述错误。学习型社会强调教育形式和地点的多样化，不仅限于学校，还包括社区、家庭、工作场所等。C选项，学校在终身学习的趋势中占据着主导地位：表述错误。学习型社会强调教育资源的多元化，学校只是其中一部分，而非唯一主导形式。D选项，学校及生活的全部时间和空间都可以用于教育：表述正确。学习型社会的核心理念是将教育融人生活的各个方面，打破时间和空间的限制，实现终身学习。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|50", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 50, "q": "马克思指出：“劳动首先是人和自然之间的过程，是人以自身的活动来中介、调整和控制人和自然之间的物质变换的过程….当他通过这种运动作用于他身外的自然并改变自然时，也就同时改变他自身的自然。”马克思的这段论述表明，将个体发展的可能性转化为现实性的因素是", "opts": ["实践活动", "环境", "遗传素质", ".学校教育"], "a": 0, "exp": "马克思的这段论述主要强调了劳动（实践活动）在人和自然之间的中介作用，以及通过这种活动，人不仅改变自然，也改变自身的自然。这里的关键在于“实践活动”这一概念，它是个体将自身发展的可能性转化为现实性的重要因素。B选项，环境：环境虽然对个体的发展有重要影响，但马克思的这段论述强调的是人通过劳动（实践活动）来改变自然和自身，而不是被动地受环境决定。环境是外部条件，而马克思更注重的是人通过实践活动主动作用于环境，从而实现自身的发展。因此，环境并不是将可能性转化为现实性的因素。C选项，遗传素质：遗传素质是个体发展的生物学基础，它为个体提供了发展的潜在可能性。然而，马克思的论述强调的是人通过劳动（实践活动）来改变自身和自然，而不是依，附录二2024年全国硕士研究生招生考试教育综合试题参考答案赖遗传素质。遗传素质只是发展的起点，而不是将可能性转化为现实性的因素。D选项，学校教育：学校教育是社会发展的重要途径，但它属于外部条件，而不是马克思这段论述的核心。马克思强调的是人通过劳动（实践活动）直接作用于自然并改变自身，而学校教育只是实践活动的一种形式，不能完全涵盖马克思所说的“劳动”这一更广泛的概念。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|51", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 51, "q": "针对学生说谎、起绰号的现象，郭老师教导学生：“你们痛恨上当受骗，那自己怎么号？”让他惊喜的是，后来在商讨和制订班规时，有学生说：“我们都不愿意被别人欺", "opts": ["显性正向功能", ".显性负向功能", "隐性正向功能", "隐性负向功能"], "a": 2, "exp": "区分教育的正向功能和负向功能主要看教育效果，题目中郭老师对学生的教育，最终起到了好的效果，所以是正向功能。区分教育的显性功能和隐性功能，主要看是否有明确的教育目的。题目中郭老师一开始只是针对学生说谎、起绰号的行为对他们进行教育。但是“惊喜的是”，学生在制定班规时，用到了郭老师之前的教育内容。解题的关键在于“惊喜”，有出乎意料的感觉，是郭老师一开始没有设定的教育目的。所以本题应选C选项，隐性正向功能。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|52", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 52, "q": "先秦儒家诸子中、苟子特别提倡尊师。下列观点中最能反映荀子尊师思想的是", "opts": ["教师是治国之本", "教师是人之模范", "教师是人伦之源", "教师是学问之本"], "a": 0, "exp": "本题为对识记性知识的考查。荀子提出“天地君亲师”，认为教师是治国之本，最能体现其尊师的观点。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|53", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 53, "q": "维新运动时期、首次专门论述师范教育、认为师范学校是“群学之基”的学者是", "opts": ["康有为", "梁启超", "严复", "王韬"], "a": 1, "exp": "本题为对识记性知识的考查。梁启超在《变法通议·论师范》中首次专门论述师范教育、认为师范学校是“群学之基”。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|54", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 54, "q": "中国近现代教育史上，首次用“职业教育”替代“实业教育”的学制是", "opts": ["壬寅学制", "癸卯学制", "壬戌学制", "戊辰学制"], "a": 2, "exp": "本题为对识记性知识的考查。在1922年颁布的壬戌学制中，用职业教育替代了实业教育的称谓。二者本质一样，均着眼实用学科知识的教授。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|55", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 55, "q": "陶行知认为，穷国解决普及教育中师资奇缺、经费匮乏、女子教育困难等问题，“最重要的钥匙”是", "opts": ["艺友制", "小先生制", "分团教学", "工学团"], "a": 1, "exp": "本题为对识记性知识的考查。陶行知认为穷国普及教育“最重要的钥匙”是小先生制。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|56", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 56, "q": "全面抗战时期，陈鹤琴在江西开展“活教育”实验，形成“活教育”理论。“活教育”的培养目标是", "opts": ["做人，做中国人，做世界人", "做人，做中国人，做现代中国人", "做中国人，做世界人，做现代人", "做人，做中国人，做现代世界人"], "a": 1, "exp": "本题为对识记性知识的考查。陈鹤琴“活教育”理论的培养目标是“做人、做中国人、做现代中国人”。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|57", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 57, "q": "古希腊时期，最早以收费授徒为职业的教师是", "opts": ["苏格拉底", "智者", "伊壁鸠鲁", "拉比"], "a": 1, "exp": "本题为对识记性知识的考查。古希腊时期最早以收费授徒为职业的教师是智者。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|58", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 58, "q": "拿破仑统治时期，法国设置帝国大学作为教育管理机构。这标志着法国形成了", "opts": ["地方分权制教育管理体制", "高等教育管理体制", "中央集权制教育管理体制", "混合式教育管理体制"], "a": 2, "exp": "本题为对识记性知识的考查。拿破仑统治时期，法国的教育管理体制是中央集权制。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|59", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 59, "q": "德国教育家福禄培尔为帮助儿童认识自然及其内在规律，专门创制的一套供儿童使用的玩具被称为", "opts": ["教具", "积木", "", "恩物"], "a": 3, "exp": "本题为对识记性知识的考查。福禄培尔为儿童创办的教具是恩物。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|60", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 60, "q": "苏联建国初期，全俄教育工作者第一次代表大会正式确立的新型学校是", "opts": ["计算学校", "不完全学校", "统一劳动学校", "综合技术学校"], "a": 2, "exp": "本题为对识记性知识的考查。苏联建国初期建立的学校为统一劳动学校。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|61", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 61, "q": "因提出“师资培训三段法”而影响英国师范教育体系走向“非定向”体制的教育报告是", "opts": ["《哈多报告》", "《詹姆斯报告》", "（罗宾斯报告》", "《斯宾斯报告》"], "a": 1, "exp": "本题为对识记性知识的考查。本题中，和师范教育有关的教育报告为《詹姆斯报告》。A选项和D选项都与中等教育有关，C选项与高等教育有关。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|62", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 62, "q": "儿童认为“脚踩在小花上，小花会感到痛的”。根据皮亚杰的认知发展理论，这种认知特点主要出现在", "opts": ["感知运动阶段", "前运算阶段", "具体运算阶段", "形式运算阶段"], "a": 1, "exp": "题目提到的是皮亚杰的泛灵论。泛灵论为前运算阶段的特征。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|63", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 63, "q": "二年级（3）班的班主任王老师对学生们说：“如果今天中午所有的同学都能做到‘光盘行动”，我就在午间给大家播放你们喜欢的动画片。”这种做法遵循的是", "opts": ["普雷马克原理", "蔡加尼克效应", "罗森塔尔效应", "耶克斯-多德森定律"], "a": 0, "exp": "普雷马克原理也被称为“祖母法则”，指的是用高频行为（喜欢做的事情）作为低频行为（不太愿意做的事情）的强化物。在这个例子中：低频行为是学生们做到“光盘行动”（可能有些学生不太愿意吃完所有食物）。高频行为是播放他们喜欢的动画片（学生们喜欢的事情）。王老师用学生们喜欢的动画片作为奖励，激励他们完成“光盘行动”，这正是普雷马克原理的应用。B选项，蔡加尼克效应：蔡加尼克效应是指人们对未完成任务的记忆比已完成任务的记附录。忆更深刻。此效应与王老师的做法无关。C选项，罗森塔尔效应：罗森塔尔效应（又称皮格马利翁效应)是指教师对学生的期望会影响学生的表现。此效应强调的是期望的作用，与王老师的做法无关。D选项，耶克斯－多德森定律：耶克斯－多德森定律描述了动机水平与任务表现之间的关系，指出适中的动机水平最有利于任务表现。此定律与王老师的做法无关。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|64", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 64, "q": "某同学参加学校的演讲比赛获得了一等奖，他把这次成功归因于自己的运气。根据归因理论，这一归因的特点是附录。", "opts": ["外部的、稳定的、可控的", "外部的、不稳定的、可控的", "外部的、稳定的、不可控的", "外部的、不稳定的、不可控的"], "a": 3, "exp": "根据韦纳的归因理论，运气是外部的、不稳定的、不可控的因素。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|65", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 65, "q": "我们头脑中贮存的“红军过草地”的故事，属于", "opts": ["陈述性知识", "程序性知识", "条件性知识", "隐性知识"], "a": 0, "exp": "陈述性知识是指关于事实、事件、概念和观念的知识，可以用语言明确表达出来。“红军过草地”是一个具体的历史事件，属于可以用语言描述的事实性知识，因此它是陈述性知识。B选项，程序性知识是指关于“如何做某事”的知识，通常涉及技能和步骤。例如：骑自行车、解数学题、做饭。“红军过草地”是一个历史事件，而不是一个操作步骤或技能，因此不属于程序性知识。C选项，条件性知识是指关于“在什么情况下使用某种知识或策略”的知识。例如：知道什么时候使用乘法而不是加法、知道什么时候使用某种学习方法。“红军过草地”是一个具体的历史事件，与条件性知识无关。D选项，隐性知识是指难以用语言表达的知识，通常通过经验获得。如：骑自行车的平衡感、艺术创作的直觉。“红军过草地”是一个可以用语言明确描述的历史事件，因此不属于隐性知识。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b89|66", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 66, "q": "儿子要求完成作业后玩一会儿游戏。爸爸对儿子说：“我很理解你做完作业后想打游戏的心情。我工作累了，有时也会通过打游戏放松一下自己。但是我们都要记住，玩游戏适可而止就好，自律对我们来讲是极为重要的品质。在这一情境中，父亲使用的品德培育方法是", "opts": ["共情、言语说服", "言语说服、角色扮演", "角色扮演、群体约定", "共情、道德讨论"], "a": 0, "exp": "在这一情境中，父亲使用的品德培育方法是共情、言语说服。共情：父亲首先表示理解儿子做完作业后想打游戏的心情，并分享自己工作累了也会通过打游戏放松的经历。这种表达方式体现了共情，即站在儿子的角度理解他的感受。言语说服：父亲接着强调“玩游戏适可而止就好，自律对我们来讲是极为重要的品质”，这是通过语言引导儿子认识自律的重要性，属于言语说服。B选项，言语说服、角色扮演：“角色扮演”是指通过模拟某种角色来体验和学习，题目中父亲并没有让儿子扮演某种角色。C选项，角色扮演、群体约定：“群体约定”通常指在群体中达成某种共识或规则，题目中父亲只是与儿子进行一对一的交流，没有涉及群体约定。亲只是简单强调了自律的重要性，并未展开深人的道德讨论。二、论述题31.【参考答案】（1）强调教师的作用。韩愈认为“人非生而知之者”，强调后天学习的重要性，学习一定要有教师指导，“学者必有师”，教师是必需的。（2）提出教师的基本任务是传道、授业、解惑。传道是传承儒家的仁义之道，授业是传习儒家六艺与古文，解惑是解决学生对于道与业的疑问，授业和解惑是为传道服务的。（3）主张以“道”为教师标准。求师以“道”为标准，“道之所存，师之所存”，不论年龄大小，不论地位贵贱，凡有道者皆可为师。。附录二2024年全国硕士研究生招生考试教育综合试题参考答案（4）主张学无常师。“闻道有先后，术业有专攻”，求学的范围不应受到限制，社会上有道之人皆可为师。（5）提倡师生相互学习。“弟子不必不如师，师不必贤于弟子”，师生关系可以相互转化，师生之间可以互相学习，弟子学有专长，亦可为师。32.【参考答案】（1）裴斯泰洛齐的要素教育理论主张，一切教育与教学均应从最简单的要素开始，然后逐渐过渡到复杂的要素。德育的要素是儿童对母亲的爱；体育的要素是儿童的关节活动；智育的要素是语言、数目和形状。（2）裴斯泰洛齐的要素教育理论为初等学校语言教学法奠定了基础。在语言教学方面，他提出教学应先从发音练习开始，然后学习周围事物的名称即单词，最后从简到繁练习把事物与名称联系起来，形成完整语句。据此，他将语言教学分为三个阶段：发音教学、单词教学和严格意义上的语言", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|67", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 67, "q": "“建国君民，教学为先”，我国向来重视教育在国家建设中的作用。2024年9月，在第40个教师节到来之际，中共中央总书记、国家主席、中央军委主席习近平出席全国教育大会并发表重要讲话。他强调，建成教育强国是近代以来中华民族梦以求的美好愿望，是实现以中国式现代化全面推进强国建设、民族复兴伟业的（）", "opts": ["先导任务、坚实基础、战略支撑", "坚实基础、战略支撑、先决条件", "战略支撑、先决条件、先导任务", "先决条件、先导任务、坚实基础"], "a": 0, "exp": "本题为对教育热点文件的考查。习近平总书记指出，建成教育强国是近代以来中华民族梦寐以求的美好愿望，是实现以中国式现代化全面推进强国建设、民族复兴伟业的先导任务、坚实基础、战略支撑。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|68", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 68, "q": "教育定义、教育口号、教育隐喻是教育领域的三种常见陈述形式。下列选项中，属于教育口号的是（）", "opts": ["“教育是农业，不是工业。”", "“人民教育人民办，办好教育为人民。”", "“教育是一种有目的的培养人的社会活动。”", "“善待问者如撞钟，叩之以小者则小鸣，叩之以大者则大鸣。”"], "a": 1, "exp": "B选项，教育口号是简洁、有号召力的短句，旨在传递特定教育理念或行动导向。“人民教育人民办，办好教育为人民”句式凝练，直接表达教育的责任主体与服务目标，具有明确倡导性，符合教育口号的特征。属于教育隐喻，排除。定，属于教育定义，排除。D选项，“善待问者如撞钟，叩之以小者则小鸣，叩之以大者则大鸣”用“撞钟”这一比喻说明教学方法，属于教育隐喻，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|69", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 69, "q": "社会对教育发展的影响可能表现在：①教育发展的规模和速度；②课程设置与内容选择；③教育领导权和受教育权；④教学方法与手段；教育管理体制。其中，生产力对教育发展的影响主要表现在（）", "opts": ["①②④", "②3④", "③④5", "①④③"], "a": 0, "exp": "“③教育领导权和受教育权”由政治制度决定，比如统治阶级掌握教育领导权，与生产力无关，排除。“③教育管理体制”受政治、文化等因素制约，比如中央集权或地方分权管理，与生产力无关，排除。确定符合题干要求的序号组合为①X2④，对应A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|70", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 70, "q": "“一切教育的真正目的，是人，即人的身体、思想和灵魂的和谐发展。”这种教育目的的价值取向属于（", "opts": ["伦理本位论", "社会本位论", "个人本位论", "生活本位论"], "a": 2, "exp": "墨子的话强调人会像染布一样，随所处环境（“苍”“黄”）改变特质；荀子的话指蓬草因生长在麻田（环境）而自然挺直，白沙因混人黑泥（环境）而变黑。两段话均突出外部环境对人身心发展的塑造作用，强调环境的影响。成长、个性完善等需求。题干中“一切教育的真正目的，是人”“人的身体、思想和灵魂的和谐发展”，直接将个体的全面发展作为教育的目的，符合个人本位论的价值取向。道德”，排除。B选项，社会本位论主张教育应服务于社会需求（如培养符合社会发展需要的人才），与题千“以人本身为目的”不符，排除。及“生活准备”，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|71", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 71, "q": "《义务教育课程方案（2022年版）》确立了今后一个时期义务教育阶段的培养目标，其核心要求是（）", "opts": ["有理想、有本领、有担当", "正确价值观、必备品格、关键能力", "健全人格、创新精神、实践能力", "全面发展、个性发展、终身发展"], "a": 0, "exp": "（义务教育课程方案（2022年版）>完善了培养目标，全面落实习近平总书记关于培养担当民族复兴大任时代新人的要求，结合义务教育性质及课程定位，从有理综合试题参考答案附录。想、有本领、有担当三个方面，明确义务教育阶段时代新人培养的具体要求。所以今后一口：个时期义务教育阶段培养目标的核心要求是“有理想、有本领、有担当”，答案为A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|72", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 72, "q": "现代教育理论所推崇的一些教学原则，在中国古代教育典籍中也有论述。下列选项中,匹配正确的是（）", "opts": ["直观性原则—“不愤不启，不排不发。举一隅不以三隅反，则不复也。”。附录三2025年全国硕士研究生招生考试教育综合试题", "因材施教原则—“求也退，故进之；由也兼人，故退之。”", "启发性原则—“其身正，不令而行；其身不正，虽令不从。”", "量力性原则一“不闻不若闻之、闻之不若见之。”"], "a": 1, "exp": "因材施教原则强调根据学生的个性差异调整教学方法。“求也退，故进之；由也兼人，故退之”指再求性格退缩，就鼓励他进取；仲由勇猛过人，就约束他言行。这正是根据学生的不同特质采取不同的教育方式，匹配因材施教原则。A选项，“不愤不启，不排不发”强调引导学生主动思考后再启发，属于启发性原则，而非直观性原则，匹配错误。C选项，“其身正，不令而行；其身不正，虽令不从”强调教师以身作则的示范作用，属于榜样示范原则，而非启发性原则，匹配错误。D选项，“不闻不若闻之，闻之不若见之”强调通过直观感知获取知识，属于直观性原则，而非量力性原则，匹配错误。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|73", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 73, "q": "李老师的班里有位学生擅长书法，但对上学不感兴趣，时常逃课。李老师让该生发起建立了书法兴趣小组、组织书法爱好者一起活动。该生逐渐喜欢上学，不再逃课，期末考试成绩也有了明显提高。李老师遵循的德育原则是（）", "opts": ["教育影响一致性原则", "严格要求与尊重学生相结合原则", "知行统一原则", "长善救失原则"], "a": 3, "exp": "长善救失原则指利用学生的优点、特长，弥补其不足或改正其缺点。李老师发现学生擅长书法的优点，通过让其发起书法兴趣小组，将其优势转化为学习动力，进而改善该生的逃课问题、提升该生的成绩，符合该原则。A选项，教育影响一致性原则强调学校、家庭、社会等多方教育力量协调一致，题干仅涉及李老师的单独教育行为，无多方协作，排除。B选项，严格要求与尊重学生相结合原则，题干未提及“严格要求”的具体行为，排除。C选项，知行统一原则侧重引导学生将道德认知转化为实际行动，题于的核心是“用优点补不足”，而非“认知与行动结合排除", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|74", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 74, "q": "王老师将学生的课堂纪律、作业完成及奖惩等情况写进学生的成长档案，在肯定学生优点的同时，指出不足之处，并提出改进建议。根据《中华人民共和国教师法》，王老师行使的教师专业权利是（）", "opts": ["参与管理权", "科学研究权", "指导评定权", "教育教学权"], "a": 2, "exp": "指导评定权是教师对学生的品行、学业等进行指导、评价并提出建议的专业权利。王老师记录学生的课堂纪律、作业完成及奖惩情况，肯定学生的优点、指出不足并提出改进建议，正是对学生发展的指导与评定，符合指导评定权的定义。A选项，参与管理权指教师参与学校民主管理（如参与教职工代表大会、提出教学改革建议）的权利，题干未涉及学校事务管理，排除。B选项，科学研究权指教师从事学术研究、发表研究成果等的权利，题干是对学生的日常评价，与科研无关，排除。D选项，教育教学权指教师开展教学活动、选择教学方法等的权利，题干核心是“评价学生”而非“实施教学”，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|75", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 75, "q": "人力资本理论认为，教育具有促进经济增长的重要功能，主要是因为教育能够（", "opts": ["提高劳动者素质", "提高劳动者的学历水平", "改变人的一般本性", "促进生产过程的社会结合"], "a": 0, "exp": "人力资本理论的核心是教育能提升人的知识、技能等人力资本，进而推动经济增长。其认为教育促进经济的关键，在于通过培养和训练提高劳动者的综合素质（如专业技能、劳动效率），这些素质是直接作用于生产、推动经济发展的核心要素。B选项，学历水平只是表面现象，背后是人的素质的提高，排除。C选项，“改变人的一般本性”表述过于抽象，排除。D选项，“促进生产过程的社会结合”是指生产中的分工协作等社会关系，与教育提升个体素质的逻辑无关，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|76", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 76, "q": "张老师在准备一节化学实验课时，将目标设定为“学生能够在实验室条件下利用所给的药品和装置制备氧气”。按课程目标取向的分类，该目标属于（", "opts": ["生成性目标", "体验性目标", "行为目标", "情感目标"], "a": 2, "exp": "行为目标的核心是用具体、可观察、可操作的行为描述目标，明确学生须完成的具体任务。张老师设定的教学目标“在实验室条件下利用所给的药品和装置制备氧气”，清晰界定了学生的操作场景、工具和具体行为，符合行为目标的特征。·附录三2025年全国硕士研究生招生考试教育综合试题参考答案A选项，生成性目标强调教学过程中自然形成的、非预设的目标，与题干中“预先设定”的实验任务不符，排除。B选项，体验性目标侧重学生在学习中的情感、态度或体验（如“感受实验探究的乐趣”），题干未涉及情感或体验层面，排除。D选项，情感目标聚焦学生情感、价值观的培养（如“树立严谨的科学态度”），题干设定的是具体的操作任务，不属于情感目标，排除。向阶段”。排除A选项。定，符合第三阶段“寻求认可”的特征。B选项正确。丙生：以“维护学校秩序、保障集体学习”为校规目的，属于第四阶段“维护权威或秩序的定向阶段”。排除C选项。丁生：以“公平对待遵守规则者”为标准，属于更高阶段的普遍道德原则的定向阶段。排除D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|77", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 77, "q": "小刚明知不能私自拿别人的东西，可是看到别的同学那里有自己喜欢的东西时，还是忍不住悄悄拿来放在自己的书包里，事后又感到愧疚和不安。根据德育过程理论，对小刚进行干预时最适合的切人点是（）", "opts": ["道德认知教育", "道德情感培养", "道德意志训练", "道德榜样示范"], "a": 2, "exp": "小刚已知“不能私自拿别人的东西”（具备正确的道德认知），事后会“感到愧疚和不安”（有道德情感），但因无法克制欲望而实施“私自拿别人的东西”这一行为，核心矛盾是道德意志薄弱A选项，道德认知教育：小刚已明确道德规范，无须再强化认知，排除。B选项，道德情感培养：小刚已有愧疚感，情感层面无明显缺失，排除。D选项，道德榜样示范：通过榜样引导行为，而小刚的问题是“自身意志不足”，并非“不知如何做”，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|78", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 78, "q": "学校正在开展“科技创意手工比赛”活动。周老师借机将说明文习作单元教学提前，指导学生创作参赛作品，且以精当的方式说明自己作品的设计意图、关键创意、主要参数，最后在发布会上进行作品展示。这个过程中，学生主要采用的学习方式是（）", "opts": ["发现学习", "项目式学习", "观察学习", "泛在学习"], "a": 1, "exp": "项目式学习以具体项目为载体，学生通过完成项目整合知识、提升能力，强调“做中学”和成果产出。周老师以“科技创意手工比赛”为项目核心，引导学生结合说明文写作完成作品设计、撰写说明、展示成果，符合项目式学习“围绕项目整合学习内容、产出具体成果”的特征。A选项，发现学习侧重学生自主探索、发现知识规律，题干是围绕比赛项目完成任务，而非“自主发现知识”，排除。C选项，观察学习是班杜拉提出的，强调榜样的重要性，不符合题意，排除。D选项，泛在学习强调利用多种场景、设备随时随地学习，题干是在教师指导下围绕特定项目开展的集中学习，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|79", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 79, "q": "某初中在研学旅行中打破班级限制，将兴趣、特点或特长相近的学生分散到不同的小组，鼓励和引导学生们各显其能，在小组中作出自己独特的贡献。这种做法依据的学生身心发展特点主要是（）", "opts": ["阶段性", "顺序性", "不平衡性", "差异性"], "a": 3, "exp": "学生身心发展的差异性指不同学生在兴趣、特长、能力等方面存在个体差异，需要因材施教。学校打破班级限制，按学生兴趣、特点分组，鼓励学生发挥独特优势，正是基于对学生个体差异性的尊重，让每个学生能在适合自己的领域贡献力量。A选项，阶段性指学生在不同年龄阶段有不同的发展任务和特点（如初中阶段侧重抽象思维发展），题干未涉及“不同阶段的发展要求”，排除。B选项，顺序性指学生的发展遵循一定顺序（如由具体到抽象、由简单到复杂），题干未体现“按一定顺序发展”的逻辑，排除。C选项，不平衡性指学生发展的速度在不同方面、不同时期存在差异（如青春期身高快速一一即无法用理智控制冲动、坚持道德原则。附录。增长），题干与“发展速度差异”无关，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|80", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 80, "q": "下列选项中，属于孔子有关教师论述的是（", "opts": ["“尊严而惮，可以为师。”", "“温故而知新，可以为师矣。”", "“诵说而不陵不犯，可以为师。”", "“师者，人之模范也。”"], "a": 1, "exp": "“温故而知新，可以为师矣”出自《论语·为政》，是孔子关于教师素养的经典论述，强调教师须具备通过温习旧知识获得新理解、新体会的能力。A选项，“尊严而惮，可以为师”出自《荀子·致士》是荀子对教师应具备威严品格的论述，排除。C选项，“诵说而不陵不犯，可以为师”同样出自《荀子·致土》，强调教师在讲授时需条理清晰、不越矩，排除。D选项，“师者，人之模范也”出自东汉班固的《白虎通义·卷七》强调教师的榜样作用，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|81", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 81, "q": "宋元是蒙学教材较为兴盛的时期，由当时学者编写的教材主要有（）", "opts": ["《三字经》《百家姓》《童蒙训》", "《三字经》《百家姓》《千字文》", "《三字经》《蒙求》《太公家教》", "《百家姓》《兔园策》《弟子规》"], "a": 0, "exp": "A选项，《三字经》相传为南宋王应麟编写，《百家姓》成书于北宋，《童蒙训》为北宋程颐之孙程端蒙所著，三者均为宋元时期学者编写的蒙学教材，符合题意。B选项，《千字文》由南朝梁周兴嗣编写，非宋元时期产物，排除。C选项，《蒙求》为唐代李瀚编写，《太公家教》成书于唐代，均早于宋元，排除。D选项，《兔园策》为唐代杜嗣先编写，《弟子规》为清代李毓秀编写，不符合题意，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|82", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 82, "q": "明末清初启蒙思想家、著名教育家黄宗羲反对封建君主专制，对学校职能有新的认识。最能体现其新认识的论述是（", "opts": ["“子产不毁乡校”", "“无人才则无政事”", "“公其非是于学校”", "“政立而后教可施”"], "a": 2, "exp": "黄宗羲对学校职能的新认识，核心是突破传统学校“仅为教化场所”的局限，主张学校应参与政治、评判是非。“公其非是于学校”意为将天下的是非判断权交给学校，使学校成为监督朝政、议论公共事务的机构，这是其区别于传统教育思想的关键A选项，“子产不毁乡校”出自《左传》讲述了春秋时期子产重视乡校，并将其作为民众议论时政场所的故事，并非黄宗羲的论述，排除。67888B选项，“无人才则无政事”是颜元的观点，强调人才对政事的重要性，是对教育培养人才功能的传统认知，排除。D选项，“政立而后教可施焉”是王夫之的观点，体现了“先有政治秩序，后有教育实施”的传统观念，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|83", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 83, "q": "1922年，北洋政府颁布了“新学制”，在《学制系统草案》标准的基础上，增加了一项新标准。该标准是（）", "opts": ["重视预科教育", "加强理科教育", "强调升学教育", "注意生活教育"], "a": 3, "exp": "1922年北洋政府颁布的“新学制”，即“壬戌学制”，其标准有七条，分别是适应社会进化之需要、发扬平民教育精神、谋个性之发展、注意国民经济力、注意生活教育、使教育易于普及、多留各地伸缩余地。其中“注意生活教育”是在《学制系统草案》标准的基础上增加的一项新标准。而重视预科教育、加强理科教育、强调升学教育均不属于“新学制”增加的新标准，所以答案为D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|84", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 84, "q": "中国人民抗日军事政治大学是抗日民主根据地干部学校的典范，其最重要的办学传统是（）", "opts": ["理论联系实际", "教育与生产劳动相结合", "自学为主，教学为辅", "政治与军事并重"], "a": 0, "exp": "本题为对教材细节的考查。中国人民抗日军事政治大学是抗日民主根据地干部学校的典范，其最重要的办学传统是理论联系实际。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|85", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 85, "q": "下列选项中，属于柏拉图教育主张的是（", "opts": ["雄辩家的首要品质是德行", "教育的最高目标在于培养哲学王", "教育属于家庭事务", "女子不宜接受体操训练和军事教育"], "a": 1, "exp": "柏拉图在《理想国》中系统阐述了其教育思想，其核心主张是教育应服务于理想国家的构建，而教育的最高目标是培养“哲学王”一一即兼具智慧、正义与理性，能凭借哲学思维治理国家的统治者。B选项正确。A选项，“雄辩家的首要品质是德行”是古罗马教育家昆体良的主张，他认为雄辩家须具备德行、智慧与口才，排除。C选项，“教育属于家庭事务”不符合柏拉图观点，他主张教育应由国家统一管理，而非由家庭主导，排除。。附录三2025年全国硕士研究生招生考试教育综合试题参考答案D选项，“女子不宜接受体操训练和军事教育”与柏拉图的主张相反，他认为女子应与男子接受同等教育，包括体操训练和军事教育，以充分发挥其才能，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|86", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 86, "q": "19世纪前半期，美国政府为促进初等教育的义务化和普及化而开展的教育革新运动是(", "opts": ["劳作学校运动", "进步教育运动", "新学校运动", "公立教育运动"], "a": 3, "exp": "19世纪前半期，美国公立教育运动的核心目标是建立由政府资助、面向全体公民的公立学校体系，推动初等教育的义务化和普及化。该运动解决了教育资源分务化和普及化”的描述。A选项，“劳作学校运动”是19世纪末20世纪初德国的教育改革运动，强调教育与生产劳动相结合，与美国无关，排除。B选项，“进步教育运动”兴起于19世纪末20世纪初，反对传统教育的刻板模式，倡导儿童中心、活动教学，并非19世纪前半期的“普及义务教育”运动，排除。C选项，“新学校运动”是19世纪末欧洲的教育革新运动，旨在建立注重实用、适应社会发展的新型学校，与美国及“19世纪前半期”的时间范围不符，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|87", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 87, "q": "德国教育家赫尔巴特提出，教学需要实现的近期的和较为直接的目的是（", "opts": ["培养儿童多方面的兴趣", "养成儿童的道德性格", "向儿童传授系统的学科知识", "造就儿童守秩序的精神"], "a": 0, "exp": "赫尔巴特将教育目的分为“可能的目的”和“必要的目的”。其中，“可能的目的”是近期、直接的目的，核心是培养儿童多方面的兴趣。B选项，“养成儿童的道德性格”是赫尔巴特提出的“必要的目的”，属于教育的终极、根本目的，而非近期直接目的，排除。C选项，“向儿童传授系统的学科知识”是实现“培养多方面兴趣”的手段，而非教育目的本身，排除。D选项，“造就儿童守秩序的精神”是赫尔巴特管理思想的体现，旨在为教学创造良好秩序，并非教育要实现的直接目的，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|88", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 88, "q": "下列选项中，体现赞科夫的发展性教学思想并有利于促进学生一般发展的策略是）", "opts": ["降低课程内容难度以调动学生积极性", "增加练习题数量以提高学生做题的准确率", "讲明知识之间的联系以帮助学生理解学习过程", "强化课外补习以提升学生学业成绩"], "a": 2, "exp": "赞科夫“发展性教学思想”的核心是促进学生“一般发展”，即学生在智力、情感、意志等方面的全面发展，关键策略包括以高难度、高速度进行教学，强调理解学习过程、理论知识起主导作用等。C选项，“讲明知识之间的联系以帮助学生理解学习过程”，符合“理解学习过程”的要求，能引导学生掌握知识逻辑、提升思维能力，从而促进一般发展。A选项，“降低课程内容难度”与赞科夫“高难度教学”原则相，低难度无法有效促进学生思维发展，排除。B选项，“增加练习题数量”侧重机械重复训练，仅能提升做题准确率，无法帮助学生理解知识本质或发展综合能力，不符合“一般发展”的要求，排除。D选项，“强化课外补习以提升学生学业成绩”聚焦短期的分数提升，以应试为导向，而非促进学生智力、情感等全面的“一般发展”，排除。体的活动引导儿童主动探索、发展反省性思维。芝加哥大学实验学校在其指导下，以儿童的兴趣和经验为中心设计课程，通过手工、游戏、观察等活动让儿童在实践中思考、解决问题，这正是活动课程的典型特征，直接服务于儿童反省性思维能力的培养。”经验为中心”的理念相，排除。C选项，“广域课程”将多个相关学科整合为一个广泛的学习领域，如“社会研究”包含历附录史、地理，仍以知识整合为核心，非杜威强调的“活动主导”，排除。D选项，“核心课程”围绕社会生活或人类共同问题，如“环境保护”展开，虽关注现实，但更侧重问题解决的知识整合，而非通过活动发展思维，与芝加哥大学实验学校的课程设计逻辑不符，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|89", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 89, "q": "根据皮亚杰的观点，学生凭借自己的想象写出“假如人类移居到火星之类的作文，说明其认知发展一般已处于（）", "opts": ["感知运动阶段", "前运算阶段", "具体运算阶段", "形式运算阶段"], "a": 3, "exp": "皮亚杰认为形式运算阶段（约11~16岁）的核心特征是个体具备抽象逻辑思维和假设-演绎推理能力，能够脱离具体事物的束缚，对抽象概念、假设性情境进行思考和推演。学生撰写“假如人类移居到火星”的作文，需要构建现实中不存在的假设性场景，体现了对抽象情境的想象与逻辑构建，符合形式运算阶段的认知特点。A选项，感知运动阶段（0~2岁）的个体以依赖感官和动作探索世界为核心，无法进行语言表达和想象创作，排除。B选项，前运算阶段（2~7岁）的个体虽有表象和初步想象，但其思维具有不可逆性、自我中心性，无法构建逻辑连贯的假设性情境，排除。C选项，具体运算阶段（7~11岁）的个体思维须依赖具体事物或经验支持，难以脱离现实进行抽象的假设性思考，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|90", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 90, "q": "娜娜坐爸爸的车上学时发现，只有系上安全带，烦人的警示音才会停止。于是，她很快就养成了上车系安全带的习惯。警示音停止对娜娜系安全带的行为来说是（）", "opts": ["替代强化", "负强化", "惩罚", "正强化"], "a": 1, "exp": "负强化的核心是“移除厌恶刺激以提高某种行为的发生频率”。娜娜的厌恶刺激是“烦人的警示音”，她系安全带的行为会让这个厌恶刺激停止，最终导致她“上车系安全带”的行为被强化、养成习惯，符合负强化的定义。A选项，替代强化指通过观察他人行为的结果来强化自身行为，娜娜是直接体验刺激变化,并非观察他人，排除.口次大活次价天C选项，惩罚指施加厌恶刺激或移除愉快刺激以减少某种行为，而题干是“养成系安全带的习惯”，与惩罚的“减少行为”目标相反，排除。D选项，正强化指给予愉快刺激来提高某种行为的发生频率，题干中“警示音停止”是“移除厌恶刺激”，而非“给予愉快刺激”，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|91", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 91, "q": "维特罗克认为，阅读是生成过程，学习是生成过程。这些论断反映了学习的（）", "opts": ["行为主义观", "人本主义观", "信息加工观", "建构主义观"], "a": 3, "exp": "维特罗克“生成学习理论”的核心观点是，学习并非被动接受信息的过程，而是学习者主动将新信息与原有知识经验结合，通过“选择、建构、整合”生成个人理解的过程。这一论断强调学习的主动性、建构性，与建构主义观中“学习者基于已有经验建构知识意义”的主张一致。A选项，行为主义观认为学习是外部刺激引发的行为改变，强调被动接受和强化训练，与维特罗克“主动生成理解”的观点相，排除。B选项，人本主义观聚焦学习者的情感、需求和自我实现，核心是“以学习者为中心”，而非强调“信息与经验的主动建构”，与生成学习理论的核心逻辑不符，排除。C选项，信息加工观将学习视为信息在大脑中“输人、存储、提取”的线性过程，虽关注内部认知，但更侧重信息的客观处理，而非学习者主动“建构知识”，排除。概括不足指对概念本质特征理解不全面，仅依据部分非本质特征判断", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|92", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 92, "q": "学习“鸟”这一概念时，小李认为企鹅不能飞，所以不属于鸟类。这一错误判断的原因可能是（", "opts": ["使用了概念的反例", "使用了类比策略", "出现了过度概括", "出现了概括不足"], "a": 3, "exp": "事物是否属于该概念。鸟的本质特征是体表覆羽、卵生、恒温脊椎动物，“会飞”并非其本质特征。小李未掌握鸟类的本质定义，因企鹅不能飞就否定其鸟类属性，属于概括不足。A选项，反例是不符合概念本质特征的事物，企鹅是鸟类的正例，并非反例，排除。，附录三2025年全国硕士研究生招生考试教育综合试题参考答案B选项，类比须通过事物间相似性推理，小李的判断未涉及将企鹅与其他事物类比，排除。C选项，过度概括是将不属于某一概念范畴的事物纳人其中，与小李将属于鸟类的企鹅排除在外的行为相反，排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b90|93", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 93, "q": "在公园里玩时，姐姐把其他小朋友丢在地上的垃圾捡起来扔进垃圾箱，并告诉：4岁的乐乐：“要把垃圾扔进垃圾箱里。”随后，乐乐看到地上有垃圾就会捡起来扔进垃圾箱。这说明，乐乐对“垃圾入箱”的态度至少已达到（", "opts": ["反应水平", "评价水平", "组织水平", "性格化水平"], "a": 0, "exp": "态度的反应水平指个体在外界影响下，能做出与榜样一致的外部行为，但尚未形成稳定的内在认知或情感认同。乐乐看到姐姐捡垃圾并听从教导，之后会模仿着将垃圾扔进垃圾箱，仅表现出与榜样一致的外部行为，符合反应水平的特点。B选项，评价水平须个体对行为有自己的判断和情感倾向，比如乐乐主动认为“捡垃圾是对的”，而乐乐目前仅是模仿行为，无明显评价，排除。C选项，组织水平须个体将该态度与其他态度整合，形成系统的态度体系，比如乐乐将“垃圾人箱”与“爱护环境”关联，题干未体现，排除。D选项，性格化水平须态度内化为稳定的性格特征，成为日常习惯且无须提醒，乐乐的行为仍依赖前期榜样影响，未达到性格化水平，排除。附：水平含义学生愿意注意某特定的接受/注意现象或刺激。反应（默认的反学生主动参与到学习活应、愿意的反应、动中，并对所学内容做出积极的反应。满意的反应）学生能够将所学内容与价值的评定自己的价值观相联系，对其重要性做出判断。学生将不同的价值观组织成一个内在一致的价价值的组织值体系，并能根据这些价值观来指导自己的行为。学生将所学的价值观念内化为自己的性格特征，品格形成（价值或价值体系个性化）形成稳定的态度和行为习惯。二、论述题31.【参考答案】（1）目的：以大学院和大学区制取代原来的教育行政制度，是为了“改官僚化为学术”，促使教育与学术结合，实现教育行政机构的学术化；使教育摆脱官的支配，达到事布卢姆情感目标分类举例学生在课堂上听到老师讲解国旗、国徽的含义，知道国家有一些重要的节日，开始意识到自己是国家的一员，对国家的概念有初步的感知。学生在参加升旗仪式时，能够自觉地行注目礼或少先队队礼，对国旗表现出尊重；在听到国歌奏响时，能主动站立，跟着旋律哼唱，从行为上表现出对国家象征的积极回应。学生得保护国旗、国徽是每个公民的责任，当看到有人破坏国旗、国徽时，能意识到这种行为是错误的，会对爱国行为表示赞赏，对不爱国的行为表示反感。学生明白爱国主义不仅仅是在特定场合表现出对国家的热爱，还体现在日常生活中对国家文化的传承、对国家利益的维护等方面。在面对一些涉及国家利益的问题时，能够从国家整体利益出发，协调个人利益与国", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}]);
